```cpp
#include <iostream>
#include <fstream>
#include <cmath>
#include <cstdlib>
#include <iomanip>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    int ax, ay, bx, by;
    plik >> ax >> ay >> bx >> by;
    int n;
    plik >> n;
    int dx = bx - ax, dy = by - ay;
    double dAB = sqrt((double)(dx * dx + dy * dy));
    int lewo = 0, prawo = 0, na = 0;
    double maxDist = -1;
    int maxX = 0, maxY = 0;
    for (int i = 0; i < n; i++) {
        int px, py;
        plik >> px >> py;
        int cross = dx * (py - ay) - dy * (px - ax);
        if (cross > 0) lewo++;
        else if (cross < 0) prawo++;
        else na++;
        double dist = abs(cross) / dAB;
        if (dist > maxDist) {
            maxDist = dist;
            maxX = px;
            maxY = py;
        }
    }
    cout << "Na lewo: " << lewo << endl;
    cout << "Na prawo: " << prawo << endl;
    cout << "Na prostej: " << na << endl;
    cout << fixed << setprecision(2);
    cout << "Najdalszy punkt: (" << maxX << "," << maxY << "), odleglosc: " << maxDist << endl;
    return 0;
}
```

